)

(ffi/defcfn ^:private c-format "jolt_chrono_DateTime_format_mv1" [:pointer :string :size_t :pointer] :int)
(defn format [self fmt]
  (dr/writeable-capture-when (fn [w__] (c-format (:ptr self) fmt (count fmt) w__)))
